// integerPoints: a probability mass function has support only on the
// integers, so it is evaluated there rather than on a fine grid.
integerPoints = (range, pmf) =&gt; {
  const xs = []
  const ys = []
  for (let k = Math.max(0, Math.ceil(range[0])); k &lt;= Math.floor(range[1]); k++) {
    xs.push(k)
    ys.push(pmf(k))
  }
  return {xs, ys}
}
