// _plotDiv is kept in a closure so Plotly reuses the same DOM node across
// reactive updates — this preserves zoom and pan when the step changes.
mainPlot = {
  const Plotly = window.Plotly
  let _plotDiv = null

  return ({visibleRows, currentRow, xRange, xBuffer, yRange, sampleXs, sampleYs}, showFCurve, showPrevMidpoints, showEndpoints, showMidpoint, showExactRoot) =&gt; {
    const data = []

