// padTableau(c, aRows, b) fills each row of aRows out to a full s x s matrix
// of coefficient strings, so an example below only has to list the entries a
// method actually uses (for an explicit method, its strictly lower triangle)
// instead of spelling out every zero.
padTableau = (c, aRows, b) =&gt; {
  const s = c.length
  const a = []
  for (let i = 0; i &lt; s; i++) {
    const row = []
    for (let j = 0; j &lt; s; j++) {
      if (j &lt; aRows[i].length) row.push(aRows[i][j])
      else row.push("0")
    }
    a.push(row)
  }
  return {a, b, c}
}







